tasks.check:
set -o pipefail; cd "$PWD"; export PYTHONPATH=$PWD TMPDIR=/tmp; PY=/home/bcorfman/dev/freytag-forge/.venv/bin/python
test -s notes.md && cp notes.md /home/bcorfman/dev/ringer-work/3c-kristin-place-notes.md || { echo "FAIL: notes.md missing"; exit 1; }
$PY -c "import storygame,sys; sys.exit(0 if storygame.__file__.startswith('$PWD') else 1)" || { echo "FAIL: not worktree"; exit 1; }
bad=$(git status --porcelain | awk '{print $2}' | grep -v -x -e notes.md -e pytest.out -e scripts/ringer/stage7/three_c_probe.py -e scripts/ringer/stage7/check_three_c_probe.py -e tests/test_3c_kristin_place.py -e tests/test_3c_carried_start.py)
test -z "$bad" || { echo "FAIL: outside ownership: $bad"; exit 1; }
git diff --quiet -- storygame data || { echo "FAIL: storygame/data edited"; exit 1; }
$PY -m pytest -q --no-cov -p no:cacheprovider tests/test_3c_kristin_place.py tests/test_3c_carried_start.py tests/test_3c_escape_result.py tests/test_3c_custody_result.py tests/test_3c_entry_package.py tests/test_3c_pump_need.py > pytest.out 2>&1; rc=$?; tail -15 pytest.out; test $rc -eq 0 || exit 1
for P in maintenance_network facility_escape; do rm -rf /tmp/kp-$P; $PY scripts/ringer/stage7/three_c_probe.py --n 1 --mode play --start postc --arms control --kristin-place $P --first-command 'Follow Michelle and the captives through the surface gates.' --semantic on --dry-run --out /tmp/kp-$P > /dev/null || exit 1; $PY scripts/ringer/stage7/check_three_c_probe.py /tmp/kp-$P 1 --mode dry || exit 1; done
rm -rf /tmp/kp-def; $PY scripts/ringer/stage7/three_c_probe.py --n 1 --mode play --start postc --arms control --first-command 'Follow Michelle and the captives through the surface gates.' --semantic on --dry-run --out /tmp/kp-def >/dev/null && grep -q kristin_place /tmp/kp-def/source.json && { echo "FAIL: default artifacts carry kristin_place"; exit 1; }
$PY -m ruff check scripts/ringer/stage7 tests/test_3c_kristin_place.py && $PY -m ruff format --check scripts/ringer/stage7 tests/test_3c_kristin_place.py || exit 1
git add -A -- scripts tests && git diff --cached -- scripts tests > /home/bcorfman/dev/ringer-work/3c-kristin-place.patch && test -s /home/bcorfman/dev/ringer-work/3c-kristin-place.patch && echo "patch exported"
